import asyncio
from pathlib import Path

async def act(page):
    """
    From the current Sales > Orders grid state (Created On: 2021-05-01 -> 2022-03-31 already applied),
    attempt to produce an Orders CSV for that date range.

    Strategy:
    1. Try to invoke the page JS export function sales_order_gridJsObject.doExport() inside
       page.expect_download() to avoid click interception by overlays.
    2. If that fails, attempt to dismiss any blocking popup by clicking close-like buttons
       (matching aria-label or inner text tokens such as 'close', '×', '✖', 'dismiss', 'x')
       and pressing Escape as a last resort.
    3. Retry the JS-export approach; if still failing, as a final fallback click the Export
       button using a full get_by_role path scoped to the Export control cell
       (page.get_by_role("cell", name="Export to: CSV Export").get_by_role("button", name="Export")).
    4. Capture the download (page.expect_download()), save to a filename, read the bytes and
       decode (UTF-8 primary, latin-1 fallback), and return a dict {'filename', 'csv'}.

    Notes about knowledge-base helpers:
    - Dashboard-focused KB helpers (generate_sales_summary_for_date_range, export_orders_csv,
      etc.) operate on the Dashboard widgets and are not suitable for exporting the full
      Sales > Orders grid over an arbitrary Created On range. Therefore they are not used.
    - The export_customers_csv_via_grid helper demonstrates the download pattern (combobox
      selection + Export + page.expect_download()), and that pattern informed the defensive
      approach here, but that helper specifically navigates to /admin/customer/ so it isn't
      reusable in-place for Sales > Orders. Hence direct Playwright interactions are used.
    """

    filename = "orders_May2021_Mar2022.csv"

    # small stabilization pause
    await asyncio.sleep(0.4)

    # Helper to attempt to dismiss overlays/popups
    async def dismiss_popups():
        # 1) Try dialog-scoped close buttons
        try:
            dialogs = page.get_by_role('dialog')
            if await dialogs.count() > 0:
                for i in range(await dialogs.count()):
                    d = dialogs.nth(i)
                    try:
                        btns = d.get_by_role('button')
                        if await btns.count() > 0:
                            for j in range(await btns.count()):
                                btn = btns.nth(j)
                                try:
                                    aria = (await btn.get_attribute('aria-label') or '').strip().lower()
                                except Exception:
                                    aria = ''
                                try:
                                    inner = (await btn.inner_text() or '').strip().lower()
                                except Exception:
                                    inner = ''
                                name = (aria + ' ' + inner).strip()
                                if any(tok in name for tok in ('close', '×', '✖', 'dismiss', 'x')):
                                    try:
                                        await btn.click()
                                        await asyncio.sleep(0.35)
                                        return True
                                    except Exception:
                                        pass
                    except Exception:
                        pass
        except Exception:
            pass

        # 2) Scan page-level buttons for common close tokens
        try:
            buttons = page.get_by_role('button')
            bcount = await buttons.count()
            for i in range(bcount):
                b = buttons.nth(i)
                try:
                    aria = (await b.get_attribute('aria-label') or '').strip().lower()
                except Exception:
                    aria = ''
                try:
                    inner = (await b.inner_text() or '').strip().lower()
                except Exception:
                    inner = ''
                name = (aria + ' ' + inner).strip()
                if any(tok in name for tok in ('close', '×', '✖', 'dismiss', 'close dialog', 'close window', 'x')):
                    try:
                        await b.click()
                        await asyncio.sleep(0.35)
                        return True
                    except Exception:
                        # continue searching
                        pass
        except Exception:
            pass

        # 3) Press Escape as a last resort
        try:
            await page.keyboard.press('Escape')
            await asyncio.sleep(0.25)
            return True
        except Exception:
            return False

    # Helper to perform export via direct JS invocation
    async def export_via_js_and_save():
        async with page.expect_download() as dl_info:
            # call the export function the Export button triggers
            await page.evaluate("() => sales_order_gridJsObject.doExport()")
        dl = await dl_info.value
        await dl.save_as(filename)
        raw = Path(filename).read_bytes()
        try:
            csv_text = raw.decode('utf-8')
        except Exception:
            csv_text = raw.decode('latin-1')
        return {'filename': filename, 'csv': csv_text}

    # Helper to perform export via clicking the scoped Export button
    async def export_via_click_and_save():
        # Locate export cell (prefer exact accessible name, fallback to contains 'export to')
        export_cell = page.get_by_role('cell', name='Export to: CSV Export')
        if await export_cell.count() == 0:
            cells = page.get_by_role('cell')
            found = None
            ccount = await cells.count()
            for i in range(ccount):
                c = cells.nth(i)
                try:
                    txt = (await c.inner_text() or '').lower()
                except Exception:
                    txt = ''
                if 'export to' in txt:
                    found = c
                    break
            if found is None:
                raise RuntimeError('Could not locate Export control cell on Sales > Orders page')
            export_cell = found

        export_btn_locator = export_cell.get_by_role('button', name='Export')
        if await export_btn_locator.count() == 0:
            btns = export_cell.get_by_role('button')
            if await btns.count() == 0:
                raise RuntimeError('Export button not found inside Export control cell')
            export_btn = btns.nth(0)
        else:
            export_btn = export_btn_locator.nth(0)

        async with page.expect_download() as dl_info:
            # use the full scoped get_by_role path for the click as required
            await export_btn.click()
        dl = await dl_info.value
        await dl.save_as(filename)
        raw = Path(filename).read_bytes()
        try:
            csv_text = raw.decode('utf-8')
        except Exception:
            csv_text = raw.decode('latin-1')
        return {'filename': filename, 'csv': csv_text}

    # 1) Try JS export first (works around overlays blocking DOM clicks)
    try:
        return await export_via_js_and_save()
    except Exception:
        # 2) Try to dismiss any popup(s) and retry
        await dismiss_popups()
        try:
            return await export_via_js_and_save()
        except Exception:
            # 3) As a final fallback, ensure CSV is selected in combobox and click Export via scoped locator
            try:
                # Ensure combobox in export cell is set to CSV if present
                export_cell = page.get_by_role('cell', name='Export to: CSV Export')
                if await export_cell.count() == 0:
                    # fallback to any cell containing 'export to'
                    cells = page.get_by_role('cell')
                    found = None
                    ccount = await cells.count()
                    for i in range(ccount):
                        c = cells.nth(i)
                        try:
                            txt = (await c.inner_text() or '').lower()
                        except Exception:
                            txt = ''
                        if 'export to' in txt:
                            found = c
                            break
                    if found is not None:
                        export_cell = found

                # If combobox present, attempt to select CSV by reading option text
                try:
                    cbs = export_cell.get_by_role('combobox')
                    if await cbs.count() > 0:
                        cb = cbs.nth(0)
                        try:
                            option_texts = await cb.evaluate("el => Array.from(el.options).map(o => o.textContent.trim())")
                        except Exception:
                            option_texts = []
                        chosen = None
                        for t in option_texts:
                            if 'csv' in (t or '').lower():
                                chosen = t
                                break
                        if chosen:
                            try:
                                await cb.select_option(label=chosen)
                            except Exception:
                                # fallback to selecting by value
                                try:
                                    opts = await cb.evaluate("el => Array.from(el.options).map(o => ({text: o.textContent.trim(), value: o.value}))")
                                except Exception:
                                    opts = []
                                for opt in opts:
                                    if 'csv' in (opt.get('text') or '').lower() and opt.get('value'):
                                        await cb.select_option(value=opt.get('value'))
                                        break
                except Exception:
                    # if anything fails here, continue to clicking export
                    pass

                # Finally, click the Export button scoped to the export_cell
                return await export_via_click_and_save()
            except Exception as final_exc:
                # Surface the final exception to the caller
                raise final_exc

