import asyncio
from pathlib import Path

async def act(page):
    """
    From the current Sales > Orders grid state (Created On: 2021-05-01 -> 2022-03-31 already applied),
    attempt to produce an Orders CSV for that date range.

    Strategy:
    1. Try to invoke the page JS export function sales_order_gridJsObject.doExport() inside
       page.expect_download() to avoid click interception by overlays.
    2. If that fails, attempt to dismiss any blocking popup by clicking close-like buttons
       (matching aria-label or inner text tokens such as 'close', '×', '✖', 'dismiss', 'x')
       and pressing Escape as a last resort.
    3. Retry the JS-export approach; if still failing, as a final fallback click the Export
       button using a full get_by_role path scoped to the Export control cell
       (page.get_by_role("cell", name="Export to: CSV Export").get_by_role("button", name="Export")).
    4. Capture the download (page.expect_download()), save to a filename, read the bytes and
       decode (UTF-8 primary, latin-1 fallback), and return a dict {'filename', 'csv'}.

    Notes about knowledge-base helpers:
    - Dashboard-focused KB helpers (generate_sales_summary_for_date_range, export_orders_csv,
      etc.) operate on the Dashboard widgets and are not suitable for exporting the full
      Sales > Orders grid over an arbitrary Created On range. Therefore they are not used.
    - The export_customers_csv_via_grid helper demonstrates the download pattern (combobox
      selection + Export + page.expect_download()), and that pattern informed the defensive
      approach here, but that helper specifically navigates to /admin/customer/ so it isn't
      reusable in-place for Sales > Orders. Hence direct Playwright interactions are used.
    """

    filename = "orders_May2021_Mar2022.csv"

    # small stabilization pause
    await asyncio.sleep(0.4)

    # Helper to attempt to dismiss overlays/popups
    async def dismiss_popups():
        # 1) Try dialog-scoped close buttons
        try:
            dialogs = page.get_by_role('dialog')
            if await dialogs.count() > 0:
                for i in range(await dialogs.count()):
                    d = dialogs.nth(i)
                    try:
                        btns = d.get_by_role('button')
                        if await btns.count() > 0:
                            for j in range(await btns.count()):
                                btn = btns.nth(j)
                                try:
                                    aria = (await btn.get_attribute('aria-label') or '').strip().lower()
                                except Exception:
                                    aria = ''
                                try:
                                    inner = (await btn.inner_text() or '').strip().lower()
                                except Exception:
                                    inner = ''
                                name = (aria + ' ' + inner).strip()
                                if any(tok in name for tok in ('close', '×', '✖', 'dismiss', 'x')):
                                    try:
                                        await btn.click()
                                        await asyncio.sleep(0.35)
                                        return True
                                    except Exception:
                                        pass
                    except Exception:
                        pass
        except Exception:
            pass

        # 2) Scan page-level buttons for common close tokens
        try:
            buttons = page.get_by_role('button')
            bcount = await buttons.count()
            for i in range(bcount):
                b = buttons.nth(i)
                try:
                    aria = (await b.get_attribute('aria-label') or '').strip().lower()
                except Exception:
                    aria = ''
                try:
                    inner = (await b.inner_text() or '').strip().lower()
                except Exception:
                    inner = ''
                name = (aria + ' ' + inner).strip()
                if any(tok in name for tok in ('close', '×', '✖', 'dismiss', 'close dialog', 'close window', 'x')):
                    try:
                        await b.click()
                        await asyncio.sleep(0.35)
